1	package com.loja.checkout.domain;
2	
3	import com.loja.checkout.domain.clube.NivelClube;
4	import com.loja.checkout.domain.clube.RegistroClube;
5	import com.loja.checkout.domain.cupom.Cupom;
6	import com.loja.checkout.domain.cupom.RegistroCupom;
7	import com.loja.checkout.domain.entrega.ModalidadeEntrega;
8	import com.loja.checkout.domain.entrega.RegistroEntrega;
9	import com.loja.checkout.domain.pagamento.FormaPagamento;
10	import com.loja.checkout.domain.pagamento.RegistroPagamento;
11	import com.loja.checkout.domain.pagamento.ResultadoPagamento;
12	import com.loja.checkout.web.ItemRequest;
13	import com.loja.checkout.web.PedidoRequest;
14	import com.loja.checkout.web.ResumoResponse;
15	import org.springframework.stereotype.Service;
16	
17	import java.math.BigDecimal;
18	import java.math.RoundingMode;
19	import java.util.List;
20	
21	@Service
22	public class CheckoutService {
23	
24	    private final RegistroEntrega registroEntrega;
25	    private final RegistroCupom registroCupom;
26	    private final RegistroClube registroClube;
27	    private final RegistroPagamento registroPagamento;
28	
29	    public CheckoutService(RegistroEntrega registroEntrega,
30	                           RegistroCupom registroCupom,
31	                           RegistroClube registroClube,
32	                           RegistroPagamento registroPagamento) {
33	        this.registroEntrega = registroEntrega;
34	        this.registroCupom = registroCupom;
35	        this.registroClube = registroClube;
36	        this.registroPagamento = registroPagamento;
37	    }
38	
39	    public ResumoResponse calcular(PedidoRequest pedido) {
40	        validarItens(pedido.itens());
41	
42	        NivelClube clube = registroClube.buscar(pedido.nivelClube())
43	                .orElseThrow(() -> new CheckoutException("NIVEL_CLUBE_INVALIDO"));
44	
45	        Regiao regiao = Regiao.buscar(pedido.regiao())
46	                .orElseThrow(() -> new CheckoutException("REGIAO_INVALIDA"));
47	
48	        ModalidadeEntrega entrega = registroEntrega.buscar(pedido.modalidadeEntrega())
49	                .orElseThrow(() -> new CheckoutException("MODALIDADE_INVALIDA"));
50	
51	        BigDecimal pesoTotal = calcularPeso(pedido.itens());
52	
53	        if (!entrega.disponivel(pesoTotal)) {
54	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
55	        }
56	
57	        BigDecimal subtotal = calcularSubtotal(pedido.itens());
58	
59	        BigDecimal freteCalculado = entrega.calcularFrete(pesoTotal);
60	        BigDecimal frete = clube.freteIsento() ? new BigDecimal("0.00") : freteCalculado;
61	
62	        BigDecimal descontoCupom = new BigDecimal("0.00");
63	        if (pedido.cupom() != null) {
64	            Cupom cupom = registroCupom.buscar(pedido.cupom())
65	                    .orElseThrow(() -> new CheckoutException("CUPOM_INVALIDO"));
66	            if (!cupom.aplicavel(subtotal, pedido.itens())) {
67	                throw new CheckoutException("CUPOM_NAO_APLICAVEL");
68	            }
69	            descontoCupom = cupom.calcularDesconto(subtotal, pedido.itens(), frete);
70	        }
71	
72	        BigDecimal seguro = regiao.taxa().multiply(subtotal).setScale(2, RoundingMode.HALF_EVEN);
73	
74	        BigDecimal totalBase = subtotal.subtract(descontoCupom).add(frete).add(seguro);
75	
76	        int parcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
77	
78	        FormaPagamento pagamento = registroPagamento.buscar(pedido.formaPagamento())
79	                .orElseThrow(() -> new CheckoutException("FORMA_PAGAMENTO_INVALIDA"));
80	
81	        if (!pagamento.aceitaParcelas(parcelas)) {
82	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
83	        }
84	
85	        if (!pagamento.disponivel(totalBase)) {
86	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
87	        }
88	
89	        ResultadoPagamento resultado = pagamento.calcular(totalBase, parcelas);
90	
91	        BigDecimal credito = clube.calcularCredito(subtotal);
92	        boolean brinde = clube.brinde(subtotal);
93	
94	        return new ResumoResponse(
95	                subtotal,
96	                descontoCupom,
97	                frete,
98	                entrega.prazoDias(),
99	                seguro,
100	                resultado.ajuste(),
101	                resultado.totalFinal(),
102	                parcelas,
103	                resultado.valorParcela(),
104	                credito,
105	                brinde
106	        );
107	    }
108	
109	    private void validarItens(List<ItemRequest> itens) {
110	        if (itens == null || itens.isEmpty()) {
111	            throw new CheckoutException("PEDIDO_INVALIDO");
112	        }
113	        for (ItemRequest item : itens) {
114	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
115	                    || item.quantidade() == null || item.quantidade() <= 0
116	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
117	                throw new CheckoutException("PEDIDO_INVALIDO");
118	            }
119	        }
120	    }
121	
122	    private BigDecimal calcularPeso(List<ItemRequest> itens) {
123	        return itens.stream()
124	                .map(i -> i.pesoKg().multiply(BigDecimal.valueOf(i.quantidade())))
125	                .reduce(BigDecimal.ZERO, BigDecimal::add);
126	    }
127	
128	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
129	        return itens.stream()
130	                .map(i -> i.precoUnitario()
131	                        .multiply(BigDecimal.valueOf(i.quantidade()))
132	                        .setScale(2, RoundingMode.HALF_EVEN))
133	                .reduce(new BigDecimal("0.00"), BigDecimal::add);
134	    }
135	}
