1	package com.loja.checkout.domain.pagamento;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	class Cartao implements FormaPagamento {
7	
8	    private static final BigDecimal TAXA_JUROS = new BigDecimal("0.0199");
9	    private static final int PARCELAS_SEM_JUROS = 3;
10	    private static final int PARCELAS_MAX = 12;
11	
12	    @Override
13	    public String codigo() { return "CARTAO"; }
14	
15	    @Override
16	    public boolean aceitaParcelas(int parcelas) {
17	        return parcelas >= 1 && parcelas <= PARCELAS_MAX;
18	    }
19	
20	    @Override
21	    public boolean disponivel(BigDecimal total) { return true; }
22	
23	    @Override
24	    public ResultadoPagamento calcular(BigDecimal total, int parcelas) {
25	        if (parcelas <= PARCELAS_SEM_JUROS) {
26	            BigDecimal valorParcela = total.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
27	            return new ResultadoPagamento(new BigDecimal("0.00"), total, valorParcela);
28	        }
29	
30	        // Tabela Price: parcela = total × taxa / (1 − (1+taxa)^−n)
31	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_JUROS);
32	        BigDecimal potencia = umMaisTaxa.pow(parcelas);
33	        BigDecimal inverso = BigDecimal.ONE.divide(potencia, 15, RoundingMode.HALF_EVEN);
34	        BigDecimal denominador = BigDecimal.ONE.subtract(inverso);
35	        BigDecimal valorParcela = total.multiply(TAXA_JUROS)
36	                .divide(denominador, 2, RoundingMode.HALF_EVEN);
37	
38	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
39	        BigDecimal ajuste = totalFinal.subtract(total);
40	        return new ResultadoPagamento(ajuste, totalFinal, valorParcela);
41	    }
42	}
