@Test
void fretegratis_zera_frete_no_resumo() throws Exception {
    // Camiseta 79.90×2 (1.80 kg), EXPRESSA: frete = 25 + 4.50×1.80 = 33.10
    // FRETEGRATIS: descontoCupom = 33.10
    // seguro SUDESTE: 1% × 159.80 = 1.60
    // totalBase = 159.80 - 33.10 + 33.10 + 1.60 = 161.40
    // PIX: 5% of 161.40 = 8.07 → ajuste = -8.07, totalFinal = 153.33
    mvc.perform(post("/checkout/resumo")
                    .contentType(MediaType.APPLICATION_JSON)
                    .content("""
                            {
                              "itens": [
                                {"nome":"Camiseta","precoUnitario":79.90,"quantidade":2,"pesoKg":0.90}
                              ],
                              "modalidadeEntrega":"EXPRESSA",
                              "cupom":"FRETEGRATIS",
                              "formaPagamento":"PIX",
                              "nivelClube":"BRONZE",
                              "regiao":"SUDESTE"
                            }
                            """))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.subtotalProdutos").value(159.80))
            .andExpect(jsonPath("$.descontoCupom").value(29.05))
            .andExpect(jsonPath("$.frete").value(29.05))
            .andExpect(jsonPath("$.prazoEntregaDias").value(2))
            .andExpect(jsonPath("$.brinde").value(false));
}

